public class HireExport {
    static void callPayroll(String hireId) {
        throw new IllegalStateException("Payroll returned 503 for " + hireId);
    }

    static String exportHire(String hireId) {
        String status = "FAILED";
        try {
            callPayroll(hireId);
            status = "SENT";
        } finally {
            System.out.println("export " + hireId + ": " + status);
            return status;
        }
    }

    public static void main(String[] args) {
        try {
            System.out.println("result " + exportHire("h-7"));
        } catch (IllegalStateException e) {
            System.out.println("retrying h-7");
        }
    }
}

