public class HireCounter {
    private volatile int hires = 0;

    void recordHire() { hires++; }

    public static void main(String[] args) throws InterruptedException {
        HireCounter counter = new HireCounter();
        Runnable work = () -> {
            for (int i = 0; i < 100_000; i++) counter.recordHire();
        };
        Thread a = new Thread(work), b = new Thread(work);
        a.start(); b.start();
        a.join(); b.join();
        System.out.println(counter.hires);
    }
}

